<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { workerPayApi as api, type PayEntry, type PayOverview, type PayWorkspace } from '../services/worker-pay';
import { workerMoneyApi, exactAmount, moneyCents, type Currency, type MoneyWorkspace } from '../services/worker-money';
import { managerSession } from '../services/manager-session';
import { managerStorefrontSelection } from '../services/manager-storefront-selection';
import { useMoneyCommand } from '../composables/useMoneyCommand';
import MoneyCommandDialog from '../components/worker-pay/MoneyCommandDialog.vue';
import { getApiErrorMessage } from '../utils/api-errors';
const props = withDefaults(defineProps<{ management?: boolean }>(), { management: false });
const workspace = ref<PayWorkspace | null>(null), overview = ref<PayOverview | null>(null), cash = ref<MoneyWorkspace | null>(null), selected = ref<number | null>(null), page = ref(1), loading = ref(false), error = ref('');
const amount = ref(''), currency = ref<Currency>('BYN'), method = ref<'cash' | 'bank'>('cash'), reason = ref('');
const scope = computed(() => `${props.management}:${managerSession.isAuthenticated.value}:${managerSession.auth.value?.staff_user_id}:${managerStorefrontSelection.selectedTenantId.value}:${managerStorefrontSelection.selectedSlug.value}`);
const canWrite = computed(() => props.management && workspace.value?.can_manage && !managerSession.auth.value?.demo_read_only);
const balance = computed(() => workspace.value?.balances.find(item => item.currency === currency.value));
const cashBalance = computed(() => cash.value?.balances.find(item => item.currency === currency.value));
const offsetAvailable = computed(() => { const held = moneyCents(cashBalance.value?.available ?? '') ?? 0n, owed = moneyCents(balance.value?.owed ?? '') ?? 0n; return fixed(held < owed ? held : owed); });
const pages = computed(() => Math.max(1, Math.ceil((workspace.value?.total ?? overview.value?.total ?? 0) / 30)));
const cashLink = computed(() => `/manager/my-money?company=${managerStorefrontSelection.selectedTenantId.value}&site=${encodeURIComponent(managerStorefrontSelection.selectedSlug.value ?? '')}`);
const status = { agreed: 'Согласовано', accrued: 'Начислено', cancelled: 'Отменено' };
const kind = { payout: 'Выплата вознаграждения', offset: 'Зачёт денег клиента', payout_reversal: 'Исправление выплаты', offset_reversal: 'Исправление зачёта' };
let generation = 0;
const load = async () => {
  const request = ++generation; loading.value = true; workspace.value = null; overview.value = null; cash.value = null; error.value = '';
  try {
    if (props.management && selected.value === null) { const result = await api.overview(page.value); if (request === generation) overview.value = result; }
    else { const result = props.management ? await api.worker(selected.value!, page.value) : await api.own(page.value); if (request !== generation) return; workspace.value = result; if (props.management && result.can_offset) { const money = await workerMoneyApi.worker(selected.value!); if (request === generation) cash.value = money; } }
  } catch (cause) { if (request === generation) error.value = getApiErrorMessage(cause); } finally { if (request === generation) loading.value = false; }
};
const command = useMoneyCommand({ scope, allowed: () => Boolean(canWrite.value && !loading.value), onSuccess: async () => { amount.value = ''; reason.value = ''; await load(); } });
const { draft, busy, pending, error: commandError, stale } = command;
const refresh = () => { command.reset(); void load(); };
const open = (id: number | null) => { if (pending.value) return; selected.value = id; page.value = 1; refresh(); };
const fixed = (value: bigint) => `${value / 100n}.${String(value % 100n).padStart(2, '0')}`;
const prepare = (offset: boolean) => {
  if (!workspace.value || !canWrite.value || pending.value || loading.value) return;
  const value = exactAmount(amount.value), owed = moneyCents(balance.value?.owed ?? '') ?? 0n, available = moneyCents(cashBalance.value?.available ?? '') ?? 0n;
  if (!value || moneyCents(value)! > owed) { error.value = 'Укажите положительную сумму не больше начисленного долга, с точностью до копеек'; return; }
  if (offset && (!workspace.value.can_offset || !cash.value || moneyCents(value)! > available)) { error.value = 'Для зачёта нужны оба финансовых права и доступные деньги клиента в той же валюте'; return; }
  const worker = selected.value!, body = { idempotency_key: crypto.randomUUID(), expected_version: workspace.value.version, amount: value, currency: currency.value }, selectedMethod = method.value;
  const label = offset ? `Зачесть ${value} ${body.currency} из денег клиента?\nДолг по вознаграждению уменьшится: ${fixed(owed)} → ${fixed(owed - moneyCents(value)!)} ${body.currency}.\nДеньги клиента на руках уменьшатся: ${cashBalance.value!.held} → ${fixed(moneyCents(cashBalance.value!.held)! - moneyCents(value)!)} ${body.currency}.` : `Учесть выплату ${value} ${body.currency} ${selectedMethod === 'cash' ? 'наличными' : 'по банку'}?\nЗапись фиксирует уже выполненную выплату. Банковский перевод не выполняется.`;
  error.value = ''; command.begin(label, () => offset ? api.offset(worker, body) : api.payout(worker, { ...body, method: selectedMethod }));
};
const reverse = (entry: PayEntry) => {
  if (!workspace.value || pending.value || !canWrite.value) return;
  const why = reason.value.trim(); if (why.length < 3) { error.value = 'Укажите причину исправления (минимум 3 символа)'; return; }
  const worker = selected.value!, body = { idempotency_key: crypto.randomUUID(), expected_version: workspace.value.version, reason: why };
  command.begin(`Исправить ${entry.kind === 'offset' ? 'зачёт' : 'выплату'} ${entry.amount} ${entry.currency}?\n${why}`, () => api.reverse(worker, entry.id, body));
};
watch(scope, () => { ++generation; selected.value = null; page.value = 1; workspace.value = null; overview.value = null; cash.value = null; amount.value = ''; reason.value = ''; if (managerSession.isAuthenticated.value) void load(); }, { immediate: true });
onBeforeUnmount(() => { ++generation; });
</script>
<template><main class="mx-auto w-full max-w-5xl space-y-5 p-4 pb-12 sm:p-6" data-testid="worker-pay"><header class="flex items-start justify-between gap-3"><div><h1 class="text-2xl font-bold">{{ management ? 'Вознаграждения монтажников' : 'Моё вознаграждение' }}</h1><p class="mt-1 text-sm text-gray-500">Согласованные работы, начисления и выплаты</p></div><button type="button" class="rounded-lg border px-3 py-2 disabled:opacity-50" :disabled="pending || loading" @click="refresh">Обновить</button></header><a v-if="!management" :href="cashLink" class="inline-block text-sm text-brand-600">Деньги клиентов — отдельно →</a><button v-if="management && selected !== null" type="button" class="text-brand-600" :disabled="pending" @click="open(null)">← Все сотрудники</button><p v-if="loading" role="status">Загружаем вознаграждения…</p><p v-if="error" role="alert" class="rounded-xl bg-red-50 p-4 text-sm text-red-800">{{ error }}</p>
<template v-if="overview"><p v-if="!overview.items.length" class="text-sm text-gray-500">Вознаграждений пока нет</p><button v-for="worker in overview.items" :key="worker.worker_profile_id!" type="button" class="block w-full rounded-xl border p-4 text-left" @click="open(worker.worker_profile_id)"><span class="font-semibold">{{ worker.display_name }}</span><span v-for="item in worker.balances" :key="item.currency" class="mt-2 block text-sm">Начислено {{ item.accrued }} {{ item.currency }} · К выплате {{ item.owed }} {{ item.currency }}</span></button></template>
<template v-if="workspace"><h2 v-if="management" class="text-lg font-semibold">{{ workspace.display_name }}</h2><div class="grid gap-3 sm:grid-cols-3"><section v-for="item in workspace.balances" :key="item.currency" class="space-y-1 rounded-xl border p-4"><h2 class="font-semibold">{{ item.currency }}</h2><p class="text-xl font-bold">{{ item.owed }} <span class="text-sm font-normal">к выплате</span></p><p class="text-sm">Согласовано: {{ item.agreed }}</p><p class="text-sm">Начислено: {{ item.accrued }}</p><p class="text-sm">Выплачено и зачтено: {{ item.paid }}</p></section></div>
<form v-if="canWrite" class="space-y-3 rounded-xl border p-4" @submit.prevent="prepare(false)"><h2 class="font-semibold">Учесть выплату</h2><div class="grid grid-cols-[1fr_6rem] gap-3"><label class="text-sm">Сумма<input v-model="amount" inputmode="decimal" aria-label="Сумма выплаты" class="mt-1 w-full rounded-lg border bg-transparent p-3" :disabled="pending || loading" /></label><label class="text-sm">Валюта<select v-model="currency" aria-label="Валюта выплаты" class="mt-1 w-full rounded-lg border bg-transparent p-3" :disabled="pending || loading"><option>BYN</option><option>USD</option><option>EUR</option></select></label></div><label class="block text-sm">Способ<select v-model="method" aria-label="Способ выплаты" class="mt-1 w-full rounded-lg border bg-transparent p-3" :disabled="pending || loading"><option value="cash">Наличные</option><option value="bank">Банк</option></select></label><p class="text-xs text-gray-500">Учитывается фактическая выплата. Банковский перевод не выполняется.</p><button type="submit" class="min-h-11 rounded-lg bg-brand-600 px-4 text-white disabled:opacity-50" :disabled="pending || loading">Учесть выплату</button><div v-if="workspace.can_offset && cash" class="space-y-2 border-t pt-3"><p class="text-sm">Деньги клиента на руках: {{ cashBalance?.held ?? '0.00' }} {{ currency }} · Доступно зачесть: {{ offsetAvailable }} {{ currency }}</p><button type="button" class="min-h-11 rounded-lg border px-4 text-sm disabled:opacity-50" :disabled="pending || loading" @click="prepare(true)">Зачесть деньги клиента в вознаграждение</button><p class="text-xs text-gray-500">Зачёт уменьшит и деньги клиента на руках, и долг по вознаграждению.</p></div></form>
<section class="space-y-3" aria-label="Согласованные вознаграждения"><h2 class="font-semibold">За работы</h2><p v-if="!workspace.agreements.length" class="text-sm text-gray-500">Вознаграждений пока нет</p><article v-for="item in workspace.agreements" :key="item.id" class="space-y-1 rounded-xl border p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-medium">{{ item.title }}</h3><span class="font-semibold">{{ item.amount }} {{ item.currency }}</span></div><p class="text-sm">{{ status[item.status] }} · Выплачено {{ item.paid }} {{ item.currency }} · Осталось {{ item.owed }} {{ item.currency }}</p><p class="text-xs text-gray-500">Заказ №{{ item.order_id }}</p></article></section>
<section class="space-y-3" aria-label="Журнал выплат"><h2 class="font-semibold">Журнал выплат</h2><p v-if="!workspace.items.length" class="text-sm text-gray-500">Выплат пока нет</p><article v-for="item in workspace.items" :key="`${item.kind}:${item.id}`" class="space-y-2 rounded-xl border p-4"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-medium">{{ kind[item.kind] }}</h3><span class="font-semibold">{{ item.amount }} {{ item.currency }}</span></div><p class="text-sm">{{ item.status === 'reversed' ? 'Исправлено' : 'Учтено' }} · {{ item.method === 'bank' ? 'Банк' : item.method === 'cash' ? 'Наличные' : 'Зачёт' }}</p><time class="block text-xs text-gray-500">{{ new Date(item.created_at).toLocaleString('ru-BY') }}</time><div v-if="canWrite && item.can_reverse" class="space-y-2"><label class="block text-sm">Причина исправления<input v-model="reason" maxlength="500" aria-label="Причина исправления выплаты" class="mt-1 block w-full rounded-lg border bg-transparent p-2" :disabled="pending" /></label><button type="button" class="min-h-10 text-sm text-red-700" :disabled="pending" @click="reverse(item)">Исправить ошибочную выплату</button></div></article></section></template>
<nav v-if="pages > 1" aria-label="Страницы вознаграждений" class="flex items-center justify-center gap-4"><button type="button" class="rounded-lg border p-3 disabled:opacity-40" :disabled="page <= 1 || pending || loading" @click="page--; refresh()">Назад</button><span>{{ page }} / {{ pages }}</span><button type="button" class="rounded-lg border p-3 disabled:opacity-40" :disabled="page >= pages || pending || loading" @click="page++; refresh()">Далее</button></nav><MoneyCommandDialog :label="draft?.label ?? null" :busy="busy" :error="commandError" :stale="stale" @confirm="command.submit" @close="command.reset" @refresh="refresh" /></main></template>
